package report

import (
	"fmt"
	"strings"
)

//==================================================================
// Types
//==================================================================

// Row is a row.
type Row struct {
	Name  string
	Sales int64
}

//==================================================================
// Functions
//==================================================================

// Render does the rendering of the rows, it goes through them and
// basically builds up the output, handling the header etc.
func Render(rows []Row) string {
	var b strings.Builder
	// header
	b.WriteString("name,sales\n")
	// rows
	for _, row := range rows {
		// write the row
		fmt.Fprintf(&b, "%s,%d\n", row.Name, row.Sales)
	}
	return b.String()
}
